script:
frappe.ui.form.on("MH_Chatbot_Consultation_Glific", {

    refresh: function(frm) {
        if (frm.doc.docstatus === 0) {
            frm.add_custom_button(__("Calculate Similarity Scores"), function() {
                calculate_similarity_via_server(frm);
            });
        }
    }

});


function calculate_similarity_via_server(frm) {

    const has_pharma = frm.doc.ai_pharmacotherapy_output && frm.doc.doctor_pharmacotherapy_output;
    const has_diagnosis = frm.doc.ai_diagnosis_output && frm.doc.doctor_diagnosis_output;

    if (!has_pharma && !has_diagnosis) {
        frappe.msgprint({
            title: __("Missing Data"),
            message: __("Please fill Pharmacotherapy and/or Diagnosis outputs before calculating."),
            indicator: "red"
        });
        return;
    }

    frappe.show_alert({ message: __("Translating & Calculating similarity..."), indicator: "blue" }, 5);

    frappe.call({
        method: "mental_health.mental_health_department.api.calculate_similarity_scores",
        args: { docname: frm.doc.name },
        freeze: true,
        freeze_message: __("Calling OpenAI — this may take 15-30 seconds..."),
        callback: function(r) {
            if (r.exc) {
                frappe.msgprint({
                    title: __("Error"),
                    message: r.exc,
                    indicator: "red"
                });
                return;
            }

            const scores = r.message;
            const updates = {};

            if (scores.pharmacotherapy_score !== null && scores.pharmacotherapy_score !== undefined) {
                updates["pharmacotherapy_similarity_score"] = scores.pharmacotherapy_score;
            }

            if (scores.diagnosis_score !== null && scores.diagnosis_score !== undefined) {
                updates["diagnosis_similarity_score"] = scores.diagnosis_score;
            }

            if (Object.keys(updates).length) {
                frm.set_value(updates).then(() => {
                    frm.save_or_update();
                    frappe.show_alert({ message: __("Similarity Scores Updated Successfully"), indicator: "green" }, 5);
                });
            } else {
                frappe.show_alert({ message: __("No scores could be computed — check field values."), indicator: "orange" }, 5);
            }
        }
    });
}

// ── Field names ────────────────────────────────────────────────
const DOCTYPE            = "MH_Chatbot_Consultation_Glific";
const SOURCE_FIELD       = "ai_diagnosis_output";
const AI_SCREENING_FIELD = "ai_screening_output";
const AI_DIAGNOSIS_FIELD = "ai_diagnosis_output_1";

// ── Frappe hooks ───────────────────────────────────────────────
frappe.ui.form.on(DOCTYPE, {
  refresh(frm) { populateMHOutputs(frm); },
  [SOURCE_FIELD](frm) { populateMHOutputs(frm); },
});

// ── Main ───────────────────────────────────────────────────────
function populateMHOutputs(frm) {
  const text = frm.doc[SOURCE_FIELD];
  if (!text || !text.trim()) return;
  if (frm.doc[AI_SCREENING_FIELD] && frm.doc[AI_DIAGNOSIS_FIELD]) return;

  // Step 1: Always extract scores directly — works for all languages
  // because PHQ-9, GAD-7, PADIS are always written in Latin script
  const scores = extractScores(text);

  // Step 2: Extract condition labels from whichever format is present
  const conditions = extractConditions(text);

  console.log("[MH] scores:", scores, "conditions:", conditions);

  // Build screening output
  const screeningLines = [];
  if (scores["PHQ-9"]) screeningLines.push(`PHQ-9: ${scores["PHQ-9"]}`);
  if (scores["GAD-7"]) screeningLines.push(`GAD-7: ${scores["GAD-7"]}`);
  if (scores["PADIS"]) screeningLines.push(`PADIS: ${scores["PADIS"]}`);

  if (!frm.doc[AI_SCREENING_FIELD] && screeningLines.length) {
    frm.set_value(AI_SCREENING_FIELD, "Screening Scores:\n" + screeningLines.join("\n"));
  }

  if (!frm.doc[AI_DIAGNOSIS_FIELD] && conditions.length) {
    frm.set_value(AI_DIAGNOSIS_FIELD, "Diagnosis:\n" + conditions.map(c => `- ${c}`).join("\n"));
  }
}

// ── Score extractor — language agnostic ────────────────────────
// PHQ-9, GAD-7, PADIS are always in Latin regardless of language.
// Finds the number that immediately follows each tool name.
// Handles formats:
//   English: (PHQ-9 score: 15)
//   Hindi:   (PHQ-9 स्कोर: 19)
//   Marathi: PHQ-9 गुण 13 आहेत
function extractScores(text) {
  const scores = {};
  const tools  = ["PHQ-9", "GAD-7", "PADIS"];

  for (const tool of tools) {
    // Escape tool name for regex (PHQ-9 → PHQ\-9)
    const escaped = tool.replace("-", "\\-");
    // Match tool name followed by any non-digit chars (score:, स्कोर:, गुण, etc.)
    // then capture the first number
    const rx = new RegExp(escaped + "[^\\d]{0,20}(\\d+)", "i");
    const m  = text.match(rx);
    if (m) scores[tool] = m[1];
  }

  return scores;
}

// ── Condition extractor ────────────────────────────────────────
function extractConditions(text) {
  // Try English bullet format first (most structured)
  const bullets = extractFromBullets(text);
  if (bullets.length) return bullets;

  // Try Hindi/Marathi: conditions in a sentence near the diagnosis heading
  return extractFromDiagnosisSentence(text);
}

// Format A — English bullets after "Based on the scores provided"
function extractFromBullets(text) {
  const items = [];
  const anchorIdx = text.search(/based on (the |provided )?scores?\s*:?/i);
  if (anchorIdx === -1) return items;

  const lines = text.slice(anchorIdx).split("\n");
  let bulletsStarted = false;

  for (const line of lines) {
    const trimmed = line.trim();
    if (/based on/i.test(trimmed)) continue;
    if (!bulletsStarted) {
      if (trimmed === "") continue;
      if (/^[-•*]/.test(trimmed)) bulletsStarted = true;
      else continue;
    }
    if (trimmed === "") break;
    if (!/^[-•*]/.test(trimmed)) break;

    // Strip bullet + bold markdown, take text before bracket
    const clean = trimmed.replace(/^[-•*]\s*/, "").replace(/\*\*/g, "").trim();
    const condition = clean.replace(/\s*\([^)]*\)/, "").trim(); // remove (PHQ-9 score: 15)
    if (condition) items.push(condition);
  }
  return items;
}

// Format B — Hindi/Marathi sentence near निदान / ### निदान heading
// Extracts condition text between tool score mentions
function extractFromDiagnosisSentence(text) {
  const conditions = [];

  // Find the diagnosis section:
  // Hindi:   "### निदान" or "**निदान**"
  // Marathi: "### निदान:" — same heading
  // English: "**Diagnosis:**" — fallback
  const headingRx = /#{1,3}\s*(निदान|diagnosis)[:\s]/i;
  const headingMatch = text.match(headingRx);

  // Get just the first paragraph after the heading
  let diagPara = "";
  if (headingMatch) {
    const afterHeading = text.slice(text.indexOf(headingMatch[0]) + headingMatch[0].length);
    // Take up to the next heading or blank-line-then-heading
    diagPara = afterHeading.split(/\n#{1,3}\s|\n\n#{1,3}\s/)[0].trim();
  } else {
    // Fallback: take first 3 lines of text
    diagPara = text.split("\n").slice(0, 3).join(" ");
  }

  // Strategy: find each tool mention and grab the condition TEXT that precedes it
  // e.g. "गंभीर अवसाद (PHQ-9 स्कोर: 19), गंभीर चिंता (GAD-7 स्कोर: 18)"
  //       ↑ condition                        ↑ condition

  // Pattern 1 — condition before bracket containing tool name
  // Matches:  (PHQ-9 ...)
  const bracketPattern = /([^\(,،।\n]{3,50}?)\s*\(\s*(PHQ[-]?9|GAD[-]?7|PADIS)[^)]*\)/gi;
  let m;
  while ((m = bracketPattern.exec(diagPara)) !== null) {
    const cond = m[1].trim().replace(/^[,،।\s]+|[,،।\s]+$/g, "").trim();
    if (cond.length > 1) conditions.push(cond);
  }

  if (conditions.length) return conditions;

  // Pattern 2 — Marathi: "PHQ-9 गुण 13 आहेत" with no condition label before tool
  // In this case the condition is described elsewhere in the sentence
  // e.g. "मध्यम नैराश्य" — extract quoted or bold text near diagnosis
  const boldOrQuoted = diagPara.match(/"([^"]{2,40})"|"([^"]{2,40})"|'([^']{2,40})'|\*\*([^*]{2,40})\*\*/g);
  if (boldOrQuoted) {
    boldOrQuoted.forEach(b => {
      const clean = b.replace(/["'*]/g, "").trim();
      if (clean.length > 1) conditions.push(clean);
    });
  }

  return conditions;
}

frappe.ui.form.on("MH_Chatbot_Consultation_Glific", {

    onload: function(frm) {
        apply_role_visibility(frm);
    },

    refresh: function(frm) {
        apply_role_visibility(frm);
    }

});

function apply_role_visibility(frm) {

    const roles = frappe.user_roles;

    const ALL_TABS = [
        "details_tab",
        "phq_tab",
        "gad2_tab",
        "padis_tab",
        "ai_output_tab",
        "doctors_output_tab",
        "similarity_scorecalculated_tab",
        "similarity_scorehuman_tab"
    ];

    // Helper to hide specific tabs and show the rest
    function show_only(visible_tabs) {
        ALL_TABS.forEach(function(tab) {
            const should_hide = !visible_tabs.includes(tab);
            frm.set_df_property(tab, "hidden", should_hide ? 1 : 0);
        });
    }

    // ─── Data Entry Operator ─────────────────────────────────────────
    // Can ONLY see Doctor Output tab
    if (roles.includes("Data Entry Operator")) {
        show_only(["doctors_output_tab"]);
        frappe.show_alert({ message: "Restricted view: Data Entry mode.", indicator: "blue" }, 3);
        return;
    }

    // ─── MH_Doctor_View ──────────────────────────────────────────────
    // Can see Patient Details, PHQ, GAD, PADIS, Doctor Output
    // CANNOT see AI Output, Similarity Score (Calculated), Similarity Score (Human)
    if (roles.includes("MH_Doctor_View")) {
        show_only([
            "details_tab",
            "phq_tab",
            "gad2_tab",
            "padis_tab",
            "doctors_output_tab"
        ]);
        return;
    }

    // ─── MH_Chatbot_Reviewer ─────────────────────────────────────────
    // Can see all EXCEPT Similarity Score (Calculated)
    if (roles.includes("MH_Chatbot_Reviewer")) {
        show_only([
            "details_tab",
            "phq_tab",
            "gad2_tab",
            "padis_tab",
            "ai_output_tab",
            "similarity_scorehuman_tab",
            "doctors_output_tab"
        ]);
        return;
    }

    // ─── System Manager / others: show all ───────────────────────────
}
